BEGIN;
CREATE FUNCTION pg_temp.assert_true(v boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION 'Meals assertion failed: %',label; END IF; END $$;
CREATE FUNCTION pg_temp.reject(q text,pattern text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE q; EXCEPTION WHEN OTHERS THEN IF SQLERRM!~pattern THEN RAISE; END IF; RETURN; END; RAISE EXCEPTION 'Expected meals rejection'; END $$;
INSERT INTO auth.users(id,email) VALUES('a0000000-0000-4000-8000-000000000021','meal-owner@example.test'),('a0000000-0000-4000-8000-000000000022','meal-peer@example.test'),('a0000000-0000-4000-8000-000000000023','meal-stranger@example.test');
SELECT pg_temp.assert_true(NOT public.kitchen_valid_diner('{"name":"Test","foo":"adult","preferences":[]}'),'unknown keys');
SELECT pg_temp.assert_true(NOT public.kitchen_valid_diner('{"name":"Test","kind":"child","preferences":[{"attribute":"ingredient","value":"allergi","direction":-1}]}'),'medical data');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000021',true);
SELECT pg_temp.assert_true(NOT public.meals_access(),'default gate closed');
SELECT pg_temp.reject($q$SELECT public.kitchen_family_change('create_household','b0000000-0000-4000-8000-000000000021',0,'{"name":"Table","displayName":"Owner","adultConfirmed":true}')$q$,'meals_denied');
RESET ROLE;
UPDATE public.kitchen_config SET enabled=true,chef_enabled=true,meals_enabled=true;
SET LOCAL ROLE authenticated;
SELECT public.kitchen_family_change('create_household','b0000000-0000-4000-8000-000000000021',0,'{"name":"Table","displayName":"Owner","adultConfirmed":true}');
SELECT pg_temp.reject($q$SELECT public.kitchen_family_change('create_household','b0000000-0000-4000-8000-000000000029',0,'{"name":"Table","displayName":"Owner"}')$q$,'meals_invalid');
SELECT public.kitchen_family_change('save_diner','c0000000-0000-4000-8000-000000000021',0,'{"document":{"name":"Private","kind":"adult","preferences":[]},"householdId":null,"shared":false}');
SELECT public.kitchen_family_change('save_diner','c0000000-0000-4000-8000-000000000022',0,'{"document":{"name":"Shared child","kind":"child","preferences":[{"attribute":"ingredient","value":"svamp","direction":-1}]},"householdId":"b0000000-0000-4000-8000-000000000021","shared":true}');
SELECT public.kitchen_invite_create('d0000000-0000-4000-8000-000000000021','b0000000-0000-4000-8000-000000000021',1,repeat('a',64));
SELECT pg_temp.reject('SELECT token_hash FROM public.kitchen_household_invites','permission denied');
SELECT pg_temp.reject('DELETE FROM public.kitchen_diners','permission denied');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000022',true);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.kitchen_diners),'stranger hidden');
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Peer',false)->>'status'='invalid','adult confirmation');
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Peer',true)->>'status'='joined','accept');
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Peer',true)->>'status'='joined','retry');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.kitchen_diners),'only shared visible');
SELECT pg_temp.reject($q$SELECT public.kitchen_family_change('save_diner','c0000000-0000-4000-8000-000000000022',1,'{}')$q$,'meals_conflict');
SELECT public.kitchen_family_change('save_diner','c0000000-0000-4000-8000-000000000023',0,'{"document":{"name":"Peer private","kind":"adult","preferences":[]},"householdId":"b0000000-0000-4000-8000-000000000021","shared":false}');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000023',true);
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Other',true)->>'status'='invalid','one use');
SELECT public.kitchen_invite_accept(repeat('z',64),'Other',true) FROM generate_series(1,10);
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Other',true)->>'status'='rate_limited','invalid attempts count');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000021',true);
SELECT public.kitchen_family_change('remove_member','b0000000-0000-4000-8000-000000000021',2,'{"userId":"a0000000-0000-4000-8000-000000000022"}');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000022',true);
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.kitchen_diners),'removed peer keeps own');
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('a',64),'Peer',true)->>'status'='invalid','old code cannot rejoin');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000021',true);
SELECT public.kitchen_invite_create('d0000000-0000-4000-8000-000000000022','b0000000-0000-4000-8000-000000000021',3,repeat('b',64));
SELECT public.kitchen_invite_revoke('d0000000-0000-4000-8000-000000000022');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000022',true);
SELECT pg_temp.assert_true(public.kitchen_invite_accept(repeat('b',64),'Peer',true)->>'status'='invalid','revoked');
RESET ROLE;
INSERT INTO public.kitchen_recipes(id,user_id) VALUES('e0000000-0000-4000-8000-000000000021','a0000000-0000-4000-8000-000000000021');
INSERT INTO public.kitchen_recipe_versions(id,recipe_id,user_id,revision,document) VALUES('e0000000-0000-4000-8000-000000000022','e0000000-0000-4000-8000-000000000021','a0000000-0000-4000-8000-000000000021',1,'{"title":"Soup","description":"","servings":2,"totalMinutes":10,"image":"none","sourceNote":"","notes":"","ingredients":[{"id":"e0000000-0000-4000-8000-000000000024","name":"Tomat","amount":1,"unit":"pcs"}],"steps":[{"id":"e0000000-0000-4000-8000-000000000025","title":"Cook","text":"Cook","timerSeconds":null}]}');
INSERT INTO public.cooking_sessions(id,user_id,recipe_version_id,revision,state,last_request_id) VALUES('e0000000-0000-4000-8000-000000000023','a0000000-0000-4000-8000-000000000021','e0000000-0000-4000-8000-000000000022',1,'{"status":"completed","activeStep":0,"servings":2,"checkedIngredientIds":[],"timers":[]}',gen_random_uuid());
INSERT INTO public.cooking_feedback(id,user_id,session_id,rating,note) VALUES(gen_random_uuid(),'a0000000-0000-4000-8000-000000000021','e0000000-0000-4000-8000-000000000023',4,'');
INSERT INTO public.wines(id,user_id,wine_name,quantity) VALUES('f0000000-0000-4000-8000-000000000021','a0000000-0000-4000-8000-000000000021','Test wine',2),('f0000000-0000-4000-8000-000000000022','a0000000-0000-4000-8000-000000000022','Peer wine',1);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000021',true);
SELECT public.kitchen_meal_save('f0000000-0000-4000-8000-000000000023',0,'{"sessionId":"e0000000-0000-4000-8000-000000000023","wineId":"f0000000-0000-4000-8000-000000000021","wineRating":5,"pairingRating":3,"note":"Nice"}');
SELECT public.kitchen_meal_save('f0000000-0000-4000-8000-000000000023',0,'{"sessionId":"e0000000-0000-4000-8000-000000000023","wineId":"f0000000-0000-4000-8000-000000000021","wineRating":5,"pairingRating":3,"note":"Nice"}');
SELECT pg_temp.assert_true((SELECT food_rating=4 AND wine_rating=5 AND pairing_rating=3 AND revision=1 FROM public.meal_wine_links),'distinct ratings and retry');
SELECT pg_temp.assert_true((SELECT quantity=2 FROM public.wines WHERE id='f0000000-0000-4000-8000-000000000021'),'stock unchanged');
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.food_signals),'no automatic memory');
SELECT pg_temp.reject($q$SELECT public.kitchen_meal_save('f0000000-0000-4000-8000-000000000023',0,'{"sessionId":"e0000000-0000-4000-8000-000000000023","wineId":"f0000000-0000-4000-8000-000000000021","wineRating":1,"pairingRating":3,"note":"Nice"}')$q$,'meals_conflict');
SELECT pg_temp.reject($q$SELECT public.kitchen_meal_save('f0000000-0000-4000-8000-000000000024',0,'{"sessionId":"e0000000-0000-4000-8000-000000000023","wineId":"f0000000-0000-4000-8000-000000000022","wineRating":null,"pairingRating":null,"note":""}')$q$,'meals_denied');
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000022',true);
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.meal_wine_links),'peer cannot read meal');
RESET ROLE;
SELECT public.reset_privacy_memory('a0000000-0000-4000-8000-000000000021');
SELECT pg_temp.assert_true((SELECT count(*)=1 FROM public.meal_wine_links),'memory reset preserves meal');
SELECT pg_temp.assert_true((SELECT document->'preferences'='[]'::jsonb FROM public.kitchen_diners WHERE id='c0000000-0000-4000-8000-000000000022'),'reset clears own preferences');
SELECT public.request_account_erasure('a0000000-0000-4000-8000-000000000021');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000021',true);
SELECT pg_temp.assert_true(NOT public.meals_access(),'erasure gates old JWT');
RESET ROLE;
DELETE FROM auth.users WHERE id='a0000000-0000-4000-8000-000000000021';
SELECT pg_temp.assert_true((SELECT count(*)=0 FROM public.meal_wine_links),'erasure cascades meals');
SELECT pg_temp.assert_true((SELECT household_id IS NULL FROM public.kitchen_diners WHERE id='c0000000-0000-4000-8000-000000000023'),'owner erase preserves peer profile');
SET LOCAL ROLE anon;
SELECT pg_temp.reject('SELECT public.meals_access()','permission denied');
SELECT pg_temp.reject('SELECT * FROM public.kitchen_diners','permission denied');
RESET ROLE;
ROLLBACK;
SELECT 'meals_households_acceptance_passed';
